BEGIN;
ALTER TABLE projects ADD COLUMN IF NOT EXISTS tenant_id text;
UPDATE projects SET tenant_id=COALESCE(NULLIF(tenant_id,''),NULLIF(metadata->>'tenant_id',''),id) WHERE tenant_id IS NULL OR tenant_id='';
ALTER TABLE projects ALTER COLUMN tenant_id SET NOT NULL;
CREATE INDEX IF NOT EXISTS projects_tenant_idx ON projects(tenant_id);
CREATE TABLE IF NOT EXISTS forge_regions(region_id text PRIMARY KEY,display_name text NOT NULL,status text NOT NULL DEFAULT 'READY' CHECK(status IN('READY','DEGRADED','DRAINING','FENCED','LOST')),health_score integer NOT NULL DEFAULT 100 CHECK(health_score BETWEEN 0 AND 100),capacity_state jsonb NOT NULL DEFAULT '{}'::jsonb,provider_regions jsonb NOT NULL DEFAULT '{}'::jsonb,last_heartbeat_at timestamptz,last_healthy_at timestamptz,observed_clock_skew_ms bigint NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_control_plane_state(id boolean PRIMARY KEY DEFAULT true CHECK(id),active_region_id text NOT NULL REFERENCES forge_regions(region_id),routing_epoch bigint NOT NULL DEFAULT 1 CHECK(routing_epoch>0),fencing_token bigint NOT NULL DEFAULT 1 CHECK(fencing_token>0),mode text NOT NULL DEFAULT 'ACTIVE' CHECK(mode IN('ACTIVE','PLANNED_FAILOVER','EMERGENCY_FAILOVER','RECOVERY','FENCED')),lease_owner text,lease_expires_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_tenant_residency_policies(tenant_id text PRIMARY KEY,home_region_id text NOT NULL REFERENCES forge_regions(region_id),active_region_id text NOT NULL REFERENCES forge_regions(region_id),allowed_region_ids jsonb NOT NULL DEFAULT '[]'::jsonb,routing_epoch bigint NOT NULL DEFAULT 1 CHECK(routing_epoch>0),data_movement_policy text NOT NULL DEFAULT 'NO_CROSS_REGION' CHECK(data_movement_policy IN('NO_CROSS_REGION','CONTROL_PLANE_ONLY','APPROVED_ARTIFACTS')),artifact_replication jsonb NOT NULL DEFAULT '{}'::jsonb,provider_region_requirements jsonb NOT NULL DEFAULT '{}'::jsonb,credentials_region_policy jsonb NOT NULL DEFAULT '{"replicate":false}'::jsonb,capacity_class text NOT NULL DEFAULT 'standard',updated_by text NOT NULL DEFAULT 'system',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forge_routing_epochs(id bigserial PRIMARY KEY,tenant_id text NOT NULL,routing_epoch bigint NOT NULL,region_id text NOT NULL REFERENCES forge_regions(region_id),fencing_token bigint NOT NULL,reason text NOT NULL,operator_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,routing_epoch));
CREATE TABLE IF NOT EXISTS forge_failover_leases(tenant_id text PRIMARY KEY,lease_id uuid NOT NULL,owner_id text NOT NULL,target_region_id text NOT NULL REFERENCES forge_regions(region_id),expected_epoch bigint NOT NULL,fencing_token bigint NOT NULL,lease_expires_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','RELEASED','EXPIRED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_failover_leases_expiry_idx ON forge_failover_leases(lease_expires_at) WHERE status='ACTIVE';
CREATE TABLE IF NOT EXISTS forge_region_health_samples(id bigserial PRIMARY KEY,region_id text NOT NULL REFERENCES forge_regions(region_id),control_plane_healthy boolean NOT NULL,postgres_healthy boolean NOT NULL,replication_healthy boolean NOT NULL,provider_healthy boolean NOT NULL,runner_capacity integer NOT NULL DEFAULT 0,clock_skew_ms bigint NOT NULL DEFAULT 0,diagnostics jsonb NOT NULL DEFAULT '{}'::jsonb,observed_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_region_health_samples_idx ON forge_region_health_samples(region_id,observed_at DESC);
CREATE TABLE IF NOT EXISTS forge_data_movement_rules(data_class text PRIMARY KEY,replication_scope text NOT NULL CHECK(replication_scope IN('NONE','CONTROL_PLANE','TENANT_METADATA','ARTIFACT_POINTER','ARTIFACT_BYTES')),cross_region_allowed boolean NOT NULL,requires_approval boolean NOT NULL DEFAULT true,rationale text NOT NULL);
INSERT INTO forge_data_movement_rules(data_class,replication_scope,cross_region_allowed,requires_approval,rationale) VALUES('CONTROL_PLANE','CONTROL_PLANE',true,false,'coordination'),('TENANT_METADATA','TENANT_METADATA',true,true,'residency-safe metadata'),('ARTIFACT_POINTER','ARTIFACT_POINTER',true,true,'policy-controlled pointers'),('ARTIFACT_BYTES','ARTIFACT_BYTES',false,true,'media bytes require explicit approval'),('CREDENTIAL_SECRET','NONE',false,true,'secrets never replicate'),('AUDIT_EVIDENCE','CONTROL_PLANE',true,false,'append-only provenance') ON CONFLICT(data_class) DO NOTHING;
INSERT INTO forge_regions(region_id,display_name,status,last_heartbeat_at,last_healthy_at) VALUES('primary','Primary region','READY',now(),now()) ON CONFLICT(region_id) DO NOTHING;
INSERT INTO forge_control_plane_state(id,active_region_id) VALUES(true,'primary') ON CONFLICT(id) DO NOTHING;
INSERT INTO forge_tenant_residency_policies(tenant_id,home_region_id,active_region_id,allowed_region_ids,updated_by) SELECT DISTINCT p.tenant_id,'primary','primary','["primary"]'::jsonb,'migration' FROM projects p ON CONFLICT(tenant_id) DO NOTHING;
ALTER TABLE forge_jobs ADD COLUMN IF NOT EXISTS tenant_id text;
ALTER TABLE forge_jobs ADD COLUMN IF NOT EXISTS execution_region text;
ALTER TABLE forge_jobs ADD COLUMN IF NOT EXISTS routing_epoch bigint;
ALTER TABLE forge_jobs ADD COLUMN IF NOT EXISTS fencing_token bigint;
ALTER TABLE forge_jobs ADD COLUMN IF NOT EXISTS residency_block_reason text;
UPDATE forge_jobs j SET tenant_id=p.tenant_id,execution_region=COALESCE(j.execution_region,r.active_region_id,'primary'),routing_epoch=COALESCE(j.routing_epoch,r.routing_epoch,1),fencing_token=COALESCE(j.fencing_token,c.fencing_token,1) FROM projects p LEFT JOIN forge_tenant_residency_policies r ON r.tenant_id=p.tenant_id CROSS JOIN forge_control_plane_state c WHERE j.project_id=p.id AND(j.tenant_id IS NULL OR j.execution_region IS NULL OR j.routing_epoch IS NULL OR j.fencing_token IS NULL);
CREATE INDEX IF NOT EXISTS forge_jobs_region_claim_idx ON forge_jobs(execution_region,status,available_at,priority,created_at) WHERE status='QUEUED';
CREATE INDEX IF NOT EXISTS forge_jobs_tenant_epoch_idx ON forge_jobs(tenant_id,routing_epoch,fencing_token);
CREATE OR REPLACE FUNCTION forge_touch_project_tenant() RETURNS trigger AS $$ BEGIN IF NEW.tenant_id IS NULL OR NEW.tenant_id='' THEN NEW.tenant_id:=COALESCE(NULLIF(NEW.metadata->>'tenant_id',''),NEW.id); END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS projects_tenant_default ON projects; CREATE TRIGGER projects_tenant_default BEFORE INSERT ON projects FOR EACH ROW EXECUTE FUNCTION forge_touch_project_tenant();
CREATE OR REPLACE FUNCTION forge_prepare_job_routing() RETURNS trigger AS $$ DECLARE p_tenant text;p_region text;p_epoch bigint;p_token bigint; BEGIN SELECT tenant_id INTO p_tenant FROM projects WHERE id=NEW.project_id; IF p_tenant IS NULL AND NEW.episode_id IS NOT NULL THEN SELECT p.tenant_id INTO p_tenant FROM episodes e JOIN projects p ON p.id=e.project_id WHERE e.id=NEW.episode_id; END IF; NEW.tenant_id:=COALESCE(NEW.tenant_id,p_tenant); IF NEW.tenant_id IS NULL THEN SELECT active_region_id,routing_epoch,fencing_token INTO p_region,p_epoch,p_token FROM forge_control_plane_state WHERE id=true; ELSE INSERT INTO forge_tenant_residency_policies(tenant_id,home_region_id,active_region_id,allowed_region_ids) SELECT NEW.tenant_id,'primary','primary','["primary"]'::jsonb WHERE NOT EXISTS(SELECT 1 FROM forge_tenant_residency_policies WHERE tenant_id=NEW.tenant_id); SELECT active_region_id,routing_epoch INTO p_region,p_epoch FROM forge_tenant_residency_policies WHERE tenant_id=NEW.tenant_id; SELECT fencing_token INTO p_token FROM forge_control_plane_state WHERE id=true; END IF; NEW.execution_region:=COALESCE(NEW.execution_region,p_region);NEW.routing_epoch:=COALESCE(NEW.routing_epoch,p_epoch);NEW.fencing_token:=COALESCE(NEW.fencing_token,p_token);RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS forge_jobs_routing_defaults ON forge_jobs; CREATE TRIGGER forge_jobs_routing_defaults BEFORE INSERT ON forge_jobs FOR EACH ROW EXECUTE FUNCTION forge_prepare_job_routing();
CREATE OR REPLACE FUNCTION forge_job_fence_valid(p_tenant text,p_region text,p_epoch bigint,p_token bigint,p_worker_region text) RETURNS boolean AS $$ DECLARE c forge_control_plane_state%ROWTYPE;t forge_tenant_residency_policies%ROWTYPE;r forge_regions%ROWTYPE; BEGIN SELECT * INTO c FROM forge_control_plane_state WHERE id=true;SELECT * INTO r FROM forge_regions WHERE region_id=p_region;IF p_worker_region IS NULL OR p_worker_region<>p_region OR r.status<>'READY' OR r.health_score<50 THEN RETURN false;END IF;IF c.active_region_id<>p_region OR c.routing_epoch<>p_epoch OR c.fencing_token<>p_token OR c.mode='FENCED' THEN RETURN false;END IF;IF p_tenant IS NOT NULL THEN SELECT * INTO t FROM forge_tenant_residency_policies WHERE tenant_id=p_tenant;IF NOT FOUND OR t.active_region_id<>p_region OR t.routing_epoch<>p_epoch OR NOT((t.allowed_region_ids @> jsonb_build_array(p_region)) OR t.home_region_id=p_region) THEN RETURN false;END IF;END IF;RETURN true;END;$$ LANGUAGE plpgsql STABLE;
CREATE OR REPLACE FUNCTION forge_residency_block_reason(p_tenant text,p_region text) RETURNS text AS $$ DECLARE t forge_tenant_residency_policies%ROWTYPE;r forge_regions%ROWTYPE;c forge_control_plane_state%ROWTYPE;BEGIN SELECT * INTO c FROM forge_control_plane_state WHERE id=true;SELECT * INTO r FROM forge_regions WHERE region_id=p_region;IF NOT FOUND OR r.status<>'READY' THEN RETURN 'REGION_UNHEALTHY';END IF;IF c.active_region_id<>p_region THEN RETURN 'STALE_ACTIVE_REGION';END IF;IF p_tenant IS NULL THEN RETURN NULL;END IF;SELECT * INTO t FROM forge_tenant_residency_policies WHERE tenant_id=p_tenant;IF NOT FOUND THEN RETURN 'RESIDENCY_POLICY_MISSING';END IF;IF t.active_region_id<>p_region THEN RETURN 'TENANT_RESIDENCY_MISMATCH';END IF;IF NOT((t.allowed_region_ids @> jsonb_build_array(p_region)) OR t.home_region_id=p_region) THEN RETURN 'REGION_NOT_ALLOWED';END IF;RETURN NULL;END;$$ LANGUAGE plpgsql STABLE;
CREATE OR REPLACE FUNCTION forge_immutable_routing_epoch() RETURNS trigger AS $$ BEGIN IF TG_OP='UPDATE' AND(OLD.tenant_id<>NEW.tenant_id OR OLD.routing_epoch<>NEW.routing_epoch OR OLD.region_id<>NEW.region_id OR OLD.fencing_token<>NEW.fencing_token) THEN RAISE EXCEPTION 'routing epochs are immutable';END IF;IF TG_OP='DELETE' THEN RAISE EXCEPTION 'routing epochs are immutable';END IF;RETURN COALESCE(NEW,OLD);END;$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS routing_epochs_immutable ON forge_routing_epochs;CREATE TRIGGER routing_epochs_immutable BEFORE UPDATE OR DELETE ON forge_routing_epochs FOR EACH ROW EXECUTE FUNCTION forge_immutable_routing_epoch();
CREATE TABLE IF NOT EXISTS forge_region_audit_evidence(id bigserial PRIMARY KEY,actor_id text NOT NULL,action text NOT NULL,tenant_id text,from_region text,to_region text,routing_epoch bigint,fencing_token bigint,evidence jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION forge_immutable_region_audit() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'region audit evidence is append-only';END;$$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS region_audit_immutable ON forge_region_audit_evidence;CREATE TRIGGER region_audit_immutable BEFORE UPDATE OR DELETE ON forge_region_audit_evidence FOR EACH ROW EXECUTE FUNCTION forge_immutable_region_audit();
COMMIT;
